import React from 'react'
import { useState, useEffect } from 'react';
import { useLocation } from 'react-router-dom';
import axios from 'axios';


const TakeQuiz = () => {
        const location = useLocation();
        const { state: formData } = location;

        const [loading, setLoading] = useState(false);
        const [error, setError] = useState(null);
        const [quizData, setQuizData] = useState(null);

        const prompt = `Generate a set of quiz questions having 4 choices and 1 correct answer based on the following data given in JSON format:

        ${JSON.stringify(formData)}

        Generate the questions in json format.`;

        const fetchQuiz = async () => {
            console.log("Loading...");
            setError(null);
            setLoading(true);
            try {
                const response = await axios({
                    url: "https://generativelanguage.googleapis.com/v1beta/models/gemini-1.5-flash:generateContent?key=YOUR_API_KEY",
                    method: "post",
                    data: {
                        contents: [{ parts: [{ text: prompt }] }],
                    },
                });
                console.log("Response:", response);

                const content = response.data?.candidates?.[0]?.content?.parts[0]?.text;

                setQuizData(content);
            } catch (err) {
                console.error("Error fetching quiz:", err);
                setError(err.message || "An error occurred while fetching the quiz questions.");
            } finally {
                setLoading(false);
            }
        };

        useEffect(() => {
            if (formData) {
                fetchQuiz();
            }
        }, [formData]);

        const stringToJson = (inputString) => {
            if (!inputString) return null;
            try {
                const cleanedString = inputString
                    .replace(/```json/g, "")
                    .replace(/```/g, "")
                    .trim();

                return JSON.parse(cleanedString);
            } catch (error) {
                console.error("Error parsing JSON:", error);
                return null;
            }
        };

        const quiz = quizData ? stringToJson(quizData) : null;

        return (
            <div className="container mx-auto p-4">
                {loading && <p className="text-center text-blue-600">Loading...</p>}
                {error && <p className="text-center text-red-600">{error}</p>}
                {quiz && quiz.quiz && (
                    <div>
                        <h3 className="text-xl font-semibold text-center mb-4">Quiz Questions</h3>
                        {quiz.quiz.map((question, index) => (
                            <div key={index} className="mb-4">
                                <p className="font-medium">{index + 1}. {question.text}</p>
                                <ul className="list-disc ml-6">
                                    {question.options.map((option, idx) => (
                                        <li key={idx}>{option}</li>
                                    ))}
                                </ul>
                            </div>
                        ))}
                    </div>
                )}
            </div>
        );
    };

    export default TakeQuiz;
